package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's periods: each named uniquely on the sheet, from and to a date inclusive, none
 * overlapping. Closing a period fixes, at that moment, each person's due-total for it (the figures
 * as shown then of their claims whose due-by falls in it that counted by the status they had at the
 * end of its last day) and carried figure (the same of their claims due in an earlier period and still
 * open at the end of its last day), and its own due-total, the sum of their due-totals. Soft-closing fixes them the same
 * way while claims due inside it can still change; a soft-closed period can then be closed (fixing
 * them afresh). A steward can reopen a closed or soft-closed period, making its figures live again.
 */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetRepository sheets;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final ClaimService claimService;
    private final SettingService settings;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetRepository sheets, ClaimRepository claims,
            PersonRepository people, ClaimService claimService, SettingService settings, Audit audit) {
        this.settings = settings;
        this.periods = periods;
        this.sheets = sheets;
        this.claims = claims;
        this.people = people;
        this.claimService = claimService;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
        if (to.isBefore(from)) throw new PeriodDatesException();
        // Lock the sheet so two users adding periods at once cannot overlap or share a name.
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        if (periods.existsBySheetIdAndName(sheetId, name)) throw new DuplicatePeriodNameException();
        if (periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new PeriodOverlapException();
        }
        Period saved = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user.strip()
                + " period=" + saved.getName() + " from=" + saved.getFromDate() + " to=" + saved.getToDate()
                + (saved.getCap() == null ? "" : " cap=" + saved.getCap()));
        return saved;
    }

    /**
     * Make one period per calendar month from the from-date's month to the to-date's month, each from
     * the first to the last day of its month and named yyyy-mm. A month whose name is already a period,
     * or whose days overlap one on the sheet, is left out; the others are still made. A blank date
     * takes the sheet's today.
     */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate fromOrNull, LocalDate toOrNull) {
        // Lock the sheet so two users adding periods at once cannot overlap or share a name.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        LocalDate from = fromOrNull == null ? today : fromOrNull;
        LocalDate to = toOrNull == null ? today : toOrNull;
        if (to.isBefore(from)) throw new PeriodDatesException();
        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (existing.stream().anyMatch(p -> p.getName().equals(name) || p.overlaps(first, last))) continue;
            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
            existing.add(saved);
            made.add(saved);
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user.strip()
                    + " period=" + saved.getName() + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
        }
        return made;
    }

    /**
     * Make the twelve monthly periods of the fiscal year named FY&lt;year&gt;, the one whose first day (the
     * first of the sheet's fiscal start month) falls in that calendar year, exactly as {@link #generate} does.
     */
    @Transactional
    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
        YearMonth first = YearMonth.of(year, settings.fiscalStartMonth(sheetId));
        return generate(sheetId, user, first.atDay(1), first.plusMonths(11).atEndOfMonth());
    }

    @Transactional
    public Period close(String sheetId, String user, Long id) {
        // Lock the sheet so no claim in the period changes while its due-total is fixed.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!settings.mayDo(sheetId, user, "close")) throw new PeriodNotPermittedException();
        if (period.isClosed()) throw new PeriodClosedException();
        return fix(sheetId, user, period, today, false, false);
    }

    @Transactional
    public Period softClose(String sheetId, String user, Long id) {
        // Lock the sheet so no claim in the period changes while its due-total is fixed.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!settings.mayDo(sheetId, user, "close")) throw new PeriodNotPermittedException();
        if (period.isClosed() || period.isSoftClosed()) throw new PeriodClosedException();
        return fix(sheetId, user, period, today, false, true);
    }

    /**
     * Close, as a close by hand would, every open period (not a soft-closed one) whose to-date plus the grace days is before the
     * sheet's today, in order of their to-dates, each audited with auto=yes. The caller holds the sheet's
     * lock, with its new today already set.
     */
    @Transactional
    public void autoClose(String sheetId, String user, LocalDate today, int graceDays) {
        List<Period> due = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
                .sorted(Comparator.comparing(Period::getToDate))
                .toList();
        for (Period period : due) fix(sheetId, user, period, today, true, false);
    }

    /** Close or soft-close the period, fixing each person's due-total for it and its own, and audit it. */
    private Period fix(String sheetId, String user, Period period, LocalDate today, boolean auto, boolean soft) {
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        // Every person on the sheet gets a figure, 0.00 when none of their claims falls in it.
        Map<Long, BigDecimal> personDues = new LinkedHashMap<>();
        for (Long personId : byId.keySet()) personDues.put(personId, BigDecimal.ZERO.setScale(2));
        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>(personDues);
        // their opening balances for it are part of what they carry into it
        period.getOpenings().forEach((personId, amount) -> {
            if (personCarried.containsKey(personId)) personCarried.merge(personId, amount, BigDecimal::add);
        });
        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !person.countsAt(claim, period.getToDate(), today)) continue;
            if (period.contains(claim.getDueBy())) {
                BigDecimal figure = claimService.chargedFigureOf(sheetId, person, claim);
                if (figure != null) personDues.merge(person.getId(), figure, BigDecimal::add);
            } else if (carriedInto(period, claim, all)) {
                BigDecimal figure = claimService.chargedFigureOf(sheetId, person, claim);
                if (figure != null) personCarried.merge(person.getId(), figure, BigDecimal::add);
            }
        }
        if (soft) period.softClose(personDues, personCarried);
        else period.close(personDues, personCarried);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + user.strip()
                + " period=" + saved.getName() + " total=" + saved.getClosedDueTotal().setScale(2).toPlainString()
                + (auto ? " auto=yes" : ""));
        return saved;
    }

    /**
     * Whether the claim is carried into the period: due in a period ending before it starts, and still
     * open (OPEN or PENDING) at the end of its last day, by the status log.
     */
    private static boolean carriedInto(Period period, Claim claim, List<Period> all) {
        Period own = all.stream().filter(p -> p.contains(claim.getDueBy())).findFirst().orElse(null);
        if (own == null || !own.getToDate().isBefore(period.getFromDate())) return false;
        ClaimStatus status = claim.statusAt(period.getToDate());
        return status != null && status.isOpen();
    }

    @Transactional
    public Period reopen(String sheetId, String user, Long id) {
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(id, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!settings.mayDo(sheetId, user, "reopen")) throw new PeriodNotPermittedException();
        if (!period.isClosed() && !period.isSoftClosed()) throw new PeriodOpenException();
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user.strip()
                + " period=" + saved.getName());
        return saved;
    }
}
package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/periods")
public class PeriodController {

    /**
     * A period as the screen shows it; once closed, with the due-total fixed then and each person's
     * due-total and carried figure for it fixed then, by person id (two decimals; empty while open). Soft-closed, the
     * figures are fixed the same way while it is not closed.
     */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, boolean closed,
            boolean softClosed, String closedDueTotal, Map<Long, String> closedPersonDues, Integer cap,
            Map<Long, String> closedPersonCarried, Map<Long, String> openings) {
        static PeriodView of(Period period) {
            Map<Long, String> personDues = new TreeMap<>();
            period.getClosedPersonDues().forEach((personId, due) -> personDues.put(personId, due.setScale(2).toPlainString()));
            Map<Long, String> carried = new TreeMap<>();
            period.getClosedPersonCarried().forEach((personId, due) -> carried.put(personId, due.setScale(2).toPlainString()));
            Map<Long, String> openings = new TreeMap<>();
            period.getOpenings().forEach((personId, amount) -> openings.put(personId, amount.setScale(2).toPlainString()));
            return new PeriodView(period.getId(), period.getName(), period.getFromDate(), period.getToDate(),
                    period.isClosed(), period.isSoftClosed(),
                    period.getClosedDueTotal() == null ? null : period.getClosedDueTotal().setScale(2).toPlainString(),
                    personDues, period.getCap(), carried, openings);
        }
    }

    /**
     * A name of letters, digits, '.', '_' or '-', a from and to date, both inclusive, and a cap on each
     * person's OPEN or PENDING claims in it (null: none).
     */
    public record PeriodRequest(
            @NotNull @Pattern(regexp = "[A-Za-z0-9._-]{1,100}") String name,
            @NotNull LocalDate from,
            @NotNull LocalDate to,
            @Positive Integer cap) {}

    /** The first and last dates whose months get a period each; blank takes the sheet's today. */
    public record GenerateRequest(LocalDate from, LocalDate to) {}

    /** A fiscal year by the calendar year its first day falls in (yyyy). */
    public record GenerateFiscalYearRequest(@NotNull @Pattern(regexp = "\\d{4}") String year) {}

    /** Lines of name,period,amount to add to people's opening balances. */
    public record OpeningImportRequest(@NotNull @Size(max = 100_000) String text) {}

    /** How many lines an opening import took, and the periods it changed as the store now holds them. */
    public record OpeningImportView(int lines, List<PeriodView> periods) {}

    private final PeriodService service;
    private final OpeningImportService openings;

    public PeriodController(PeriodService service, OpeningImportService openings) {
        this.service = service;
        this.openings = openings;
    }

    @GetMapping
    public List<PeriodView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.list(sheetId).stream().map(PeriodView::of).toList();
    }

    @PostMapping
    public PeriodView add(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PeriodRequest request) {
        return PeriodView.of(service.add(sheetId, user, request.name(), request.from(), request.to(), request.cap()));
    }

    /** Make a period for each month from the from-date's to the to-date's: those made, earliest first. */
    @PostMapping("/generate")
    public List<PeriodView> generate(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody GenerateRequest request) {
        return service.generate(sheetId, user, request.from(), request.to()).stream().map(PeriodView::of).toList();
    }

    /** Make the fiscal year's twelve monthly periods as generate does: those made, earliest first. */
    @PostMapping("/generate-fy")
    public List<PeriodView> generateFiscalYear(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid GenerateFiscalYearRequest request) {
        return service.generateFiscalYear(sheetId, user, Integer.parseInt(request.year())).stream()
                .map(PeriodView::of).toList();
    }

    /** Add each pasted line's amount to the person's opening balance for the period; any bad line refuses them all. */
    @PostMapping("/openings")
    public OpeningImportView importOpenings(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid OpeningImportRequest request) {
        OpeningImportService.Result result = openings.importOpenings(sheetId, user, request.text());
        return new OpeningImportView(result.lines(), result.periods().stream().map(PeriodView::of).toList());
    }

    @PostMapping("/{id}/close")
    public PeriodView close(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.close(sheetId, user, id));
    }

    @PostMapping("/{id}/soft-close")
    public PeriodView softClose(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.softClose(sheetId, user, id));
    }

    @PostMapping("/{id}/reopen")
    public PeriodView reopen(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.reopen(sheetId, user, id));
    }
}
package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;
import java.util.TreeMap;

/**
 * A period of the sheet: a name unique on the sheet, from and to a date, both inclusive. Once
 * closed, its due-total and each person's due-total and carried figure for it are fixed at what they were when it was
 * closed; reopened, they are live again. Soft-closed, its figures are fixed the same way, but claims
 * due inside it can still change.
 */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether it is soft-closed: its figures fixed, its claims still free to change. Never with closed. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** The due-total fixed when the period was closed or soft-closed; none while it is open. */
    @Column(name = "closed_due_total", precision = 14, scale = 2)
    private BigDecimal closedDueTotal;

    /** Each person's due-total for it fixed when it was closed, by person id; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_due", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "due_total", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> closedPersonDues = new TreeMap<>();

    /** Each person's carried figure for it fixed when it was closed, by person id; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> closedPersonCarried = new TreeMap<>();

    /** Each person's opening balance for it, the pasted amounts added up, by person id; part of their carried figure. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_opening", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> openings = new TreeMap<>();

    /** The most OPEN or PENDING claims a person may have in it; null for no cap. */
    @Column(name = "claim_cap")
    private Integer cap;

    protected Period() {}

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer cap) {
        this(sheetId, name, fromDate, toDate);
        this.cap = cap;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public String getName() { return name; }

    public LocalDate getFromDate() { return fromDate; }

    public LocalDate getToDate() { return toDate; }

    public boolean isClosed() { return closed; }

    public boolean isSoftClosed() { return softClosed; }

    public BigDecimal getClosedDueTotal() { return closedDueTotal; }

    public Map<Long, BigDecimal> getClosedPersonDues() { return closedPersonDues; }

    public Map<Long, BigDecimal> getClosedPersonCarried() { return closedPersonCarried; }

    public Integer getCap() { return cap; }

    public Map<Long, BigDecimal> getOpenings() { return openings; }

    /** Add the amount to the person's opening balance for it. */
    public void addOpening(Long personId, BigDecimal amount) {
        openings.merge(personId, amount, BigDecimal::add);
    }

    /** Close it, fixing each person's due-total and carried figure for it and its own due-total, the sum of theirs. */
    public void close(Map<Long, BigDecimal> personDues, Map<Long, BigDecimal> personCarried) {
        fix(personDues, personCarried);
        this.closed = true;
        this.softClosed = false;
    }

    /** Soft-close it, fixing its figures as a close does while its claims can still change. */
    public void softClose(Map<Long, BigDecimal> personDues, Map<Long, BigDecimal> personCarried) {
        fix(personDues, personCarried);
        this.softClosed = true;
    }

    private void fix(Map<Long, BigDecimal> personDues, Map<Long, BigDecimal> personCarried) {
        this.closedPersonDues.clear();
        this.closedPersonDues.putAll(personDues);
        this.closedPersonCarried.clear();
        this.closedPersonCarried.putAll(personCarried);
        this.closedDueTotal = personDues.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen it: its due-total and carried figures are live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedDueTotal = null;
        this.closedPersonDues.clear();
        this.closedPersonCarried.clear();
    }

    /** Whether the date falls in it, both ends inclusive. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether it shares a date with the other dates, both inclusive. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !from.isAfter(toDate);
    }
}
